    api_version=&#34;2024-05-01-preview&#34;,
    api_key=os.getenv(&#34;AOAI_KEY&#34;))

GPT_MODEL = &#34;gpt-35-turbo&#34;

response = client.chat.completions.create(     #1
    model=GPT_MODEL,                         #2
    messages = [                             #3
      ↪{&#34;role&#34;:&#34;system&#34;,&#34;content&#34;:&#34;You are an AI assistant 
